{
  "$schema": "https://open-design.ai/schemas/plugin.v1.json",
  "specVersion": "1.0.0",
  "name": "example-hps-bauhaus",
  "title": "Teach Design Fundamentals like a World-Class Studio Mentor",
  "title_i18n": {
    "en": "Teach Design Fundamentals like a World-Class Studio Mentor",
    "zh-CN": "像世界级工作室导师一样教设计基础",
    "zh-TW": "像世界级工作室导师一样教设计基础"
  },
  "version": "1.0.0",
  "description": "A visual-design fundamentals course for new brand designers — grid, type, color, and the exercises that build the eye. Built as a decision-grade professional training deck for junior designers, new hires.",
  "description_i18n": {
    "en": "A visual-design fundamentals course for new brand designers — grid, type, color, and the exercises that build the eye. Built as a decision-grade professional training deck for junior designers, new hires.",
    "zh-CN": "像世界级工作室导师一样教设计基础——一份可商业交付的培训交付 Deck，围绕真实主题、证据链与决策目标组织。",
    "zh-TW": "像世界级工作室导师一样教设计基础——一份可商业交付的培训交付 Deck，围绕真实主题、证据链与决策目标组织。"
  },
  "license": "MIT",
  "author": {
    "name": "lewislulu",
    "url": "https://github.com/lewislulu"
  },
  "homepage": "https://github.com/lewislulu/html-ppt-skill",
  "plugin": {
    "repo": "https://github.com/lewislulu/html-ppt-skill"
  },
  "tags": [
    "community",
    "deck",
    "slides",
    "bauhaus",
    "geometric",
    "primary-colors",
    "design-history",
    "html-ppt",
    "design",
    "brand",
    "visual-system",
    "hps-bauhaus",
    "professional-training",
    "employee-onboarding-deck",
    "education",
    "training-deck",
    "workshop",
    "course-module",
    "decision-deck",
    "commercial-slide-agent"
  ],
  "compat": {
    "agentSkills": [
      {
        "path": "./SKILL.md"
      }
    ]
  },
  "od": {
    "kind": "scenario",
    "taskKind": "new-generation",
    "mode": "deck",
    "scenario": "education",
    "surface": "web",
    "preview": {
      "type": "html",
      "entry": "./example.html",
      "motion": "deck"
    },
    "useCase": {
      "query": {
        "en": "Create \"Teach Design Fundamentals like a World-Class Studio Mentor\" as a decision-grade Professional training deck in this template's own visual system. Subject: A visual-design fundamentals course for new brand designers — grid, type, color, and the exercises that build the eye. Audience: junior designers, new hires. First ask only for missing essentials: audience, decision target, source-of-truth materials, deadline, and must-keep numbers. Then produce the slide plan, written slides, visual direction, speaker-ready structure, and a critic pass against this rubric: can a learner perform the target task the next day.",
        "zh-CN": "像世界级工作室导师一样教设计基础。像世界级工作室导师一样教设计基础——一份可商业交付的培训交付 Deck，围绕真实主题、证据链与决策目标组织。 主题：A visual-design fundamentals course for new brand designers — grid, type, color, and the exercises that build the eye. 先确认受众、决策目标、素材来源、截止时间和必须保留的数据，再输出叙事主线、页面规划、逐页文案、视觉方向和按评审标准自检的版本。"
      },
      "exampleOutputs": [
        {
          "path": "./example.html",
          "title": "Teach Design Fundamentals like a World-Class Studio Mentor",
          "title_i18n": {
            "en": "Teach Design Fundamentals like a World-Class Studio Mentor",
            "zh-CN": "像世界级工作室导师一样教设计基础",
            "zh-TW": "像世界级工作室导师一样教设计基础"
          }
        }
      ]
    },
    "inputs": [
      {
        "name": "deckType",
        "label": "Deck type",
        "type": "select",
        "required": true,
        "options": [
          "design review deck",
          "product launch deck",
          "annual report deck",
          "tech-sharing deck",
          "pitch deck",
          "course module"
        ],
        "default": "design review deck"
      },
      {
        "name": "topic",
        "label": "Topic",
        "type": "string",
        "required": true,
        "placeholder": "What the deck is about",
        "default": "the user's brief"
      },
      {
        "name": "audience",
        "label": "Audience",
        "type": "string",
        "required": true,
        "placeholder": "Designers, execs, students, clients…",
        "default": "a general audience"
      },
      {
        "name": "slideCount",
        "label": "Pages",
        "type": "select",
        "required": true,
        "options": [
          "8-10 pages",
          "10-15 pages",
          "15-20 pages"
        ],
        "default": "8-10 pages"
      }
    ],
    "context": {
      "skills": [
        {
          "path": "./SKILL.md"
        }
      ],
      "assets": [
        "./example.html"
      ]
    },
    "pipeline": {
      "stages": [
        {
          "id": "discovery",
          "atoms": [
            "discovery-question-form"
          ]
        },
        {
          "id": "generate",
          "atoms": [
            "file-write",
            "live-artifact"
          ]
        }
      ]
    },
    "capabilities": [
      "prompt:inject",
      "fs:write"
    ],
    "category": "professional-training"
  }
}
